      "proposed_laureates": [
        "Antoine Georges",
        "Dieter Vollhardt",
        "Gabriel Kotliar"
      ],
      "assessment": {
        "nobel_worthiness": "Dynamical mean-field theory made strongly correlated electronic matter quantitatively tractable and changed the working language of the field.",
        "attribution": "Vollhardt's limit and Georges and Kotliar's formulation and implementation form a coherent foundational attribution.",
        "maturity": "It is an established, widely validated framework with extensive experimental connections and methodological descendants.",
        "uncertainties": [
          "Its mean-field character limits direct exactness in finite-dimensional materials."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B019",
      "proposed_laureates": [
        "Immanuel Bloch",
        "Markus Greiner",
        "Peter Zoller"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattices became an exceptionally clean and controllable realization of quantum many-body models.",
        "attribution": "Zoller made decisive theoretical contributions, while Bloch and Greiner established landmark experimental control and observation.",
        "maturity": "The platform has generated reproducible many-body physics over more than two decades.",
        "uncertainties": [
          "Several further theorists and experimental groups have comparably strong claims to foundational credit."
        ]
      }
    },
    {
