        "Alexei Kitaev",
        "Andrew M. Steane",
        "Peter W. Shor"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum error correction supplied the conceptual mechanism that makes scalable quantum information processing physically conceivable.",
        "attribution": "Shor's code, Steane's independent code construction, and Kitaev's foundational formulations are central contributions.",
        "maturity": "The ideas are theoretically mature and increasingly demonstrated in hardware, though fault-tolerant scale remains unfinished.",
        "uncertainties": [
          "A large community contributed essential architectures, thresholds, and implementations."
        ]
      }
    },
